DROP TABLE orders; DROP TABLE users;
CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, country TEXT, signup_date DATE NOT NULL);
CREATE TABLE orders (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), amount NUMERIC(10, 2) NOT NULL CHECK (amount >= 0), status TEXT NOT NULL DEFAULT 'paid', created_at TIMESTAMP NOT NULL);
INSERT INTO users SELECT g, 'user' || g, (ARRAY['US','UK','DE','FR',NULL])[1 + g % 5], DATE '2023-01-01' + (g % 400) FROM generate_series(1, 1000) g;
INSERT INTO orders SELECT g, 1 + (g * 7919) % 1000, round((g * 37 % 50000) / 100.0, 2), (ARRAY['paid','paid','paid','refunded','pending'])[1 + g % 5], TIMESTAMP '2024-01-01' + (g * 613 % 525600) * INTERVAL '1 minute' FROM generate_series(1, 20000) g;
VACUUM ANALYZE;
EXPLAIN SELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);
EXPLAIN SELECT * FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);
EXPLAIN SELECT * FROM users u WHERE u.id IN (SELECT user_id FROM orders WHERE amount > 400);
EXPLAIN SELECT * FROM users u WHERE u.id IN (SELECT user_id FROM orders WHERE status = 'refunded');
EXPLAIN SELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id AND o.amount > 450);
EXPLAIN SELECT * FROM users u WHERE u.id NOT IN (SELECT user_id FROM orders WHERE amount > 400);
EXPLAIN SELECT * FROM orders o WHERE o.user_id IN (SELECT id FROM users WHERE country = 'US');
EXPLAIN SELECT * FROM orders o WHERE EXISTS (SELECT 1 FROM users u WHERE u.id = o.user_id AND u.country = 'DE');
EXPLAIN SELECT u.name, (SELECT count(*) FROM orders o WHERE o.user_id = u.id) AS n FROM users u;
EXPLAIN SELECT * FROM users u WHERE u.id = 5 AND EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);
EXPLAIN SELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id) OR u.country = 'US';
EXPLAIN SELECT * FROM orders WHERE amount > (SELECT avg(amount) FROM orders);
EXPLAIN SELECT * FROM users WHERE id IN (SELECT user_id FROM orders WHERE amount > (SELECT avg(amount) FROM orders));
CREATE INDEX idx_orders_user ON orders (user_id);
EXPLAIN SELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);
EXPLAIN SELECT * FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);
EXPLAIN SELECT u.name, (SELECT count(*) FROM orders o WHERE o.user_id = u.id) AS n FROM users u;
EXPLAIN SELECT * FROM users u WHERE u.id < 10 AND EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);
